   }

   try {
      Result::err(new \RuntimeException('the api said no'))->valueOrThrow('could not load user 5');
   } catch (\Optional\Exceptions\MissingValueException $e) {
      echo $e->getPrevious()?->getMessage(), "\n"; // "the api said no", kept as the cause
