   echo Option::someNotFalsy(false), "\n"; // None
   echo Option::someNotFalsy('Ada'), "\n"; // Some('Ada')

   // A throwing call
   echo Option::fromCallable(fn() => 7), "\n";                             // Some(7)
   echo Option::fromCallable(fn() => throw new Exception("no")), "\n";     // None
}

